/* بيانات ركن tawsiyat: تُحمَّل عند أول فتح للقسم */
window.TAWSIYAT = {"ch":[{"id":"jami","t":"الوصايا الجامعة","d":"مواضع جمعت فيها الآيات أصول الوصايا في موضع واحد، منها ما نصّت الآية فيه على قوله تعالى «ذلكم وصّاكم به» وهي الوصايا العشر في سورة الأنعام."},{"id":"luqman","t":"وصية لقمان لابنه","d":"ما حكاه القرآن من وعظ لقمان الحكيم لابنه، وقد جاء في أثنائه وصية الله تعالى بالوالدين."},{"id":"ibada","t":"في العقيدة والعبادة","d":"توصيات ربانية في التقوى والعبادة وإقامة الدين والصلاة والذكر والشكر والصبر."},{"id":"usra","t":"في الأسرة والوالدين","d":"توصيات في برّ الوالدين ورعاية الأولاد وحسن العشرة وحفظ الأهل."},{"id":"akhlaq","t":"في الأخلاق والكلام والآداب","d":"توصيات في القول السديد والعفو والتثبّت وحفظ الأعراض وآداب الاستئذان وغضّ البصر."},{"id":"mal","t":"في المال والمعاملات","d":"توصيات في أكل المال بالحق وتوثيق الديون وترك الربا والوفاء بالعقود والإنفاق ومال اليتيم والوصية."},{"id":"mujtama","t":"في المجتمع والعدل والدعوة","d":"توصيات في أداء الأمانات والقيام بالقسط والتعاون على البرّ والإصلاح بين الناس والدعوة بالحكمة وطاعة أولي الأمر بالمعروف."},{"id":"tawasi","t":"التواصي بالحق والصبر والمرحمة","d":"آيات جعلت التواصي نفسه خُلُقاً للمؤمنين: أن يوصي بعضهم بعضاً بالحق والصبر والرحمة."}],"i":[{"id":"an151","ch":"jami","t":"الوصايا العشر: الأولى إلى الخامسة","r":[6,151],"n":"خمس وصايا: تحريم الشرك بالله، ثم الإحسان إلى الوالدين، ثم النهي عن قتل الأولاد من فقر، واجتناب الفواحش ما ظهر منها وما بطن، وعدم قتل النفس التي حرّم الله إلا بالحق، وتُختم بقوله «ذلكم وصّاكم به لعلكم تعقلون».","wd":1,"q":{"w":"السعدي","bk":"saadi","s":6,"ay":151,"x":"{ذلكم}: المذكور، {وصَّاكم}[الله]{به لعلَّكم تعقِلون}: عن الله وصيَّته ثم تحفظونها ثم تراعونها وتقومونَ بها. ودلَّت الآية على أنه بحسب عقل العبد يكون قيامه بما أمر الله به.","en":"\"That\" which is mentioned, \"He has enjoined upon you that you may use reason\": that you understand His counsel from Allah, then preserve it, then observe it and act on it. The verse shows that a person's fulfilment of what Allah commands is in proportion to his reason."}},{"id":"an152","ch":"jami","t":"الوصايا العشر: السادسة إلى التاسعة","r":[6,152],"n":"أربع وصايا: ألا يُقرب مال اليتيم إلا بالتي هي أحسن، وإيفاء الكيل والميزان بالقسط، والعدل في القول ولو كان ذا قربى، والوفاء بعهد الله؛ وتُختم بقوله «ذلكم وصّاكم به لعلكم تذكّرون».","wd":1,"q":{"w":"السعدي","bk":"saadi","s":6,"ay":152,"x":"{وبعهد الله أوفوا}: وهذا يشملُ العهد الذي عاهده عليه العباد؛ من القيام بحقوقه والوفاء بها، ومن العهد الذي يقع التعاهد به بين الخلق؛ فالجميع يجب الوفاءُ به، ويحرُم نقضُه والإخلال به. {ذلكم}: الأحكام المذكورة، {وصَّاكُم}[الله]{به لعلَّكم تَذَكَّرونَ}: ما بيَّنه لكم من الأحكام، وتقومون بوصية الله لكم حقَّ القيام، وتعرفون ما فيها من الحِكم والأحكام.","en":"\"And fulfil the covenant of Allah\": this includes the covenant made with Allah by servants, to uphold His rights and fulfil them, and the covenants made between people; all of it must be fulfilled and breaking or neglecting it is forbidden. \"That is what He has enjoined upon you that you may remember\": what He has explained to you of the rulings, so that you uphold Allah's counsel as it should be upheld and understand the wisdom and rulings in it."}},{"id":"an153","ch":"jami","t":"الوصايا العشر: العاشرة والصراط المستقيم","r":[6,153],"n":"والوصية العاشرة: هذا صراط الله مستقيماً فيجب اتباعه، وتُنهى الأمة عن اتباع السبل المتفرقة التي تفرّق عن سبيله، وتُختم بقوله «ذلكم وصّاكم به لعلكم تتقون».","wd":1,"q":{"w":"السعدي","bk":"saadi","s":6,"ay":153,"x":"ولما بيَّن كثيراً من الأوامر الكبار والشرائع المهمَّة؛ أشار إليها وإلى ما هو أعمُّ منها، فقال:{وأنَّ هذا صراطي مستقيماً}؛ أي: هذه الأحكام وما أشبهها مما بيَّنه الله في كتابه ووضَّحه لعباده صراطُ الله الموصل إليه وإلى دار كرامته المعتدل السهل المختصر. {فاتَّبِعوه}: لتنالوا الفوزَ والفلاح، وتدركوا الآمالَ والأفراح، {ولا تتَّبِعوا السُّبُلَ}؛ أي: الطرق المخالفة لهذا الطريق، {فتفرَّقَ بكم عن سبيلِهِ}؛ أي: تضلُّكم عنه وتفرِّقكم يميناً وشمالاً؛ فإذا ضللتُم عن الصراط المستقيم؛ فليس ثمَّ إلا طرق توصِلُ إلى الجحيم. {ذلكم وصَّاكم به لعلَّكم تتَّقون}: فإنكم إذا قمتُم بما بيَّنه الله لكم علماً وعملاً؛ صرتُم من المتَّقين وعباد الله المفلحين.","en":"When He had explained many of the great commands and important laws, He pointed to them and to what is more general, saying \"And that this is My path, straight\": these rulings and what resembles them, which Allah explained in His Book and made clear to His servants, are Allah's path leading to Him and to the abode of His honour, balanced, easy and direct. \"So follow it\": so that you attain success and fulfil your hopes; \"and do not follow the other ways\", those opposing this way, \"for they will separate you from His way\", leading you astray right and left; and if you stray from the straight path there remain only roads that lead to Hell. \"That is what He has enjoined upon you that you may become righteous\": for if you uphold what Allah has made clear to you in knowledge and action, you become of the righteous and successful servants of Allah."}},{"id":"isra23","ch":"jami","t":"عبادة الله وحده وبرّ الوالدين","r":[17,23,25],"n":"قضاء الله أن لا يُعبد إلا هو، وأن يُحسَن إلى الوالدين، ويُلزَم الأدب معهما عند كِبَرهما فلا يُقال لهما «أفٍّ» ويُقال لهما قولاً كريماً ويُخفض لهما جناح الذل من الرحمة.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":17,"ay":23,"x":"ثم ذكر بعد حقِّه القيام بحقِّ الوالدين، فقال:{وبالوالدين إحساناً}؛ أي: أحسنوا إليهما بجميع وجوه الإحسان القوليِّ والفعليِّ؛ لأنهما سببُ وجود العبد، ولهما من المحبَّة للولد والإحسان إليه، والقرب ما يقتضي تأكُّد الحقِّ ووجوب البرِّ. {إمَّا يَبۡلُغَنَّ عندَكَ الكِبَرَ أحدُهما أو كلاهما}؛ أي: إذا وصلا إلى هذا السنِّ الذي تضعُفُ فيه قواهما ويحتاجان من اللُّطف والإحسان ما هو معروفٌ، {فلا تَقُلۡ لهما أفٍّ}: وهذا أدنى مراتب الأذى، نبَّه به على ما سواه، والمعنى: لا تؤذِهِما أدنى أذيَّة، {ولا تَنۡهَرۡهُما}؛ أي: تزجُرهما وتتكلَّم لهما كلاماً خشناً. {وقلۡ لهما قولاً كريماً}: بلفظٍ يحبَّانه، وتأدَّب وتلطَّف بكلام ليِّن حسن يلذُّ على قلوبهما، وتطمئنُّ به نفوسهما، وذلك يختلفُ باختلاف الأحوال والعوائد والأزمان.","en":"Then, after His own right, He mentioned fulfilling the right of parents, saying \"and to parents, kindness\": be good to them in every way, in word and deed, for they are the cause of a person's existence and have such love for the child, kindness toward him and closeness as make the right firm and dutifulness obligatory. \"If one or both of them reach old age with you\", an age at which their strength weakens and they need the kindness and gentleness that is customary, \"do not say to them 'uff'\": the least degree of harm, mentioned to alert to all that exceeds it, meaning do not harm them in the slightest; \"and do not repel them\", that is, scold them or speak harshly to them. \"And speak to them a generous word\": in words they love, with courtesy and gentle, good speech that delights their hearts and calms their souls, which varies with circumstances, customs and times."}},{"id":"isra26","ch":"jami","t":"حقّ القربى والمسكين والاعتدال في الإنفاق","r":[17,26,30],"n":"إيتاء ذي القربى والمسكين وابن السبيل حقّهم، والنهي عن التبذير، وعدم جعل اليد مغلولة إلى العنق ولا بسطها كل البسط.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":17,"ay":26,"x":"يقول تعالى: {وآت ذا القُربى حقَّه}: من البرِّ والإكرام الواجب والمسنون، وذلك الحقُّ يتفاوت بتفاوت الأحوال والأقارب والحاجة وعدمها والأزمنة، {والمسكينَ}: آته حقَّه من الزَّكاة ومن غيرها؛ لتزول مسكنتُه، {وابنَ السبيل}: وهو الغريب المنقطع به عن بلده، فيُعْطى الجميع من المال، على وجهٍ لا يضرُّ المعطي، ولا يكون زائداً على المقدار اللائق؛ فإنَّ ذلك تبذيرٌ، قد نهى الله عنه وأخبر: إنَّ المبذِّرين {إخوانُ الشياطين} …","en":"Allah the Exalted says: \"And give the relative his right\", of kindness and honour, obligatory and recommended, a right that varies with conditions, kin, need or lack of it, and times; \"and the needy\": give him his right of zakah and otherwise so that his neediness is removed; \"and the wayfarer\": the stranger cut off from his land. All are given of the wealth in a way that does not harm the giver and does not exceed the fitting measure, for that is squandering which Allah has forbidden, and He declared that the squanderers \"are brothers of the devils\" …"}},{"id":"isra31","ch":"jami","t":"حفظ الأنفس والأعراض والأموال والعهود","r":[17,31,35],"n":"النهي عن قتل الأولاد خشية الفقر، وعن قربان الزنا، وعن قتل النفس التي حرّم الله إلا بالحق، وعن قربان مال اليتيم إلا بالتي هي أحسن، والأمر بالوفاء بالعهد وبإيفاء الكيل والوزن بالقسطاس المستقيم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":17,"ay":31,"x":"وهذا من رحمته بعباده؛ حيث كان أرحم بهم من والديهم، فنهى الوالدين أن يقتُلوا أولادهم خوفاً من الفقر والإملاق، وتكفَّل برزق الجميع، وأخبر أنَّ:{قَتۡلَهم كان خِطۡئاً كبيراً}؛ أي: من أعظم كبائر الذنوب؛ لزوال الرحمة من القلب، والعقوق العظيم، والتجرِّي على قتل الأطفال الذين لم يجرِ منهم ذنبٌ ولا معصيةٌ.","en":"This is from His mercy toward His servants, for He is more merciful to them than their own parents: He forbade parents to kill their children for fear of poverty, took responsibility for providing for all, and declared that \"killing them is ever a great sin\", that is, one of the gravest major sins, for it removes mercy from the heart, is the worst disobedience of duty, and shows audacity in killing children who have committed no wrong or sin."}},{"id":"isra36","ch":"jami","t":"التثبّت من العلم والتواضع في المشي","r":[17,36,39],"n":"لا يتبع الإنسان ما ليس له به علم، فالسمع والبصر والفؤاد مسؤولة، ولا يمشي في الأرض مرحاً، فإنه لن يخرق الأرض ولن يبلغ الجبال طولاً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":17,"ay":36,"x":"أي: ولا تتَّبع ما ليس لك به علم، بل تثبَّت في كلِّ ما تقوله وتفعله؛ فلا تظنَّ ذلك يذهب لا لك ولا عليك. {إنَّ السمع والبصر والفؤاد كلُّ أولئك كان عنه مسؤولاً}: فحقيق بالعبد الذي يعرف أنه مسؤول عما قاله وفعله وعما استعمل به جوارحه التي خلقها الله لعبادته أن يُعِدَّ للسؤال جواباً، وذلك لا يكون إلاَّ باستعمالها بعبوديَّة الله، وإخلاص الدِّين له، وكفِّها عما يكرهه الله تعالى.","en":"That is: do not pursue what you have no knowledge of; rather, verify everything you say and do, and do not think it will pass without consequence for or against you. \"Indeed the hearing, the sight and the heart, all of those will be questioned\": so it is fitting for a servant who knows he is accountable for what he said and did, and for how he used the faculties Allah created for His worship, to prepare an answer for the questioning, which happens only by using them in the service of Allah, devoting religion sincerely to Him and restraining them from what Allah dislikes."}},{"id":"nisa36","ch":"jami","t":"الإحسان إلى كل ذي حق","r":[4,36],"n":"عبادة الله وحده بلا شرك، والإحسان إلى الوالدين وذي القربى واليتامى والمساكين والجار ذي القربى والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت الأيمان، وأن الله لا يحب المختال الفخور.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":36,"x":"يأمر تعالى عباده بعبادتِهِ وحدَه لا شريك له، وهو الدخول تحت رقِّ عبوديَّتِهِ والانقياد لأوامره ونواهيه محبةً وذلًّا وإخلاصاً له في جميع العبادات الظاهرة والباطنة، وينهى عن الشرك به شيئاً، لا شركاً أصغر، ولا أكبر …","en":"Allah the Exalted commands His servants to worship Him alone with no partner, which is to enter under the yoke of His servitude and submit to His commands and prohibitions with love, humility and sincerity in all outward and inward acts of worship, and He forbids associating anything with Him, neither minor nor major …"}},{"id":"nahl90","ch":"jami","t":"العدل والإحسان وإيتاء ذي القربى","r":[16,90],"n":"أمر الله بالعدل والإحسان وإيتاء ذي القربى، ونهى عن الفحشاء والمنكر والبغي، وهو يعظ عباده لعلهم يتذكرون.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":16,"ay":90,"x":"فصارت هذه الآية جامعةً لجميع المأمورات والمنهيَّات، لم يبقَ شيءٌ إلاَّ دخل فيها. فهذه قاعدةٌ ترجع إليها سائر الجزئيَّات؛ فكلُّ مسألة مشتملة على عدل أو إحسان أو إيتاء ذي القربى؛ فهي مما أمر الله به، وكلُّ مسألةٍ مشتملة على فحشاء أو منكَر أو بغي؛ فهي مما نهى الله عنه، وبها يُعْلَمُ حُسنُ ما أمر الله به وقُبح ما نهى عنه، وبها يُعتبر ما عند الناس من الأقوال، وتردُّ إليها سائر الأحوال؛ فتبارَكَ مَن جعل في كلامِهِ الهدى والشفاء والنور والفرقان بين جميع الأشياء، ولهذا قال:{يعظِكُم}؛ به، أي: بما بيَّنه لكم في كتابه بأمركم بما فيه غاية صلاحكم ونهيكم عما فيه مضرَّتكم.","en":"So this verse became comprehensive of all commands and prohibitions; nothing is left that does not fall under it. It is a rule to which all particulars return: every matter that contains justice, excellence or giving to relatives is among what Allah commanded, and every matter that contains indecency, wrongdoing or oppression is among what He forbade; by it the goodness of what Allah commanded and the ugliness of what He forbade become known, and people's sayings are measured by it and all conditions are referred to it. Blessed is He who placed in His speech guidance, healing, light and the criterion between all things; hence He says \"He admonishes you\", by what He has made clear in His Book, commanding you what is most beneficial and forbidding you what harms you."}},{"id":"baq177","ch":"jami","t":"حقيقة البرّ","r":[2,177],"n":"ليس البرّ توجيه الوجوه قبل المشرق والمغرب، بل الإيمان بالله واليوم الآخر والملائكة والكتاب والنبيين، وإيتاء المال على حبه لأهل الحاجة، وإقامة الصلاة وإيتاء الزكاة، والوفاء بالعهد، والصبر في البأساء والضراء وحين البأس.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":177,"x":"{أولئك}؛ أي: المتصفون بما ذكر من العقائد الحسنة والأعمال التي هي آثار الإيمان وبرهانه ونوره والأخلاق التي هي جمال الإنسان وحقيقة الإنسانية فأولئك {الذين صدقوا}؛ في إيمانهم لأن أعمالهم صدقت إيمانهم {وأولئك هم المتقون}؛ لأنهم تركوا المحظور وفعلوا المأمور، لأن هذه الأمور مشتملة على كل خصال الخير تضمناً ولزوماً لأن الوفاء بالعهد يدخل فيه الدين كله، ولأن العبادات المنصوص عليها في هذه الآية أكبر العبادات، ومن قام بها كان بما سواها أقوم، فهؤلاء [هم] الأبرار الصادقون المتقون.","en":"\"Those\": those described with the good beliefs and deeds that are the traces, proof and light of faith, and the character that is the beauty and reality of humanity, are \"the ones who have been true\" in their faith because their deeds proved their faith, \"and it is they who are the righteous\", because they left what is forbidden and did what is commanded. These matters contain all virtues, by implication and necessity, because fulfilling covenants includes the whole religion, and because the acts of worship named in this verse are the greatest; whoever upholds them is more upright in everything else. They are the righteous, truthful, God-fearing."}},{"id":"luq12","ch":"luqman","t":"النهي عن الشرك","r":[31,12,13],"n":"أول وصية: الأمر بشكر الله، وأول ما وعظ به لقمان ابنه: «لا تشرك بالله إن الشرك لظلم عظيم».","wd":0,"q":{"w":"السعدي","bk":"saadi","s":31,"ay":13,"x":"{وإذ قال لقمانُ لابنِهِ وهو يَعِظُهُ}؛ أو: قال له قولاً به يعظه، والوعظُ: الأمرُ والنهيُ المقرون بالترغيب والترهيب؛ فأمَرَهُ بالإخلاص ونهاه عن الشرك وبيَّن له السبب في ذلك، فقال:{إنَّ الشركَ لظلمٌ عظيمٌ}: ووجه كونه عظيماً أنَّه لا أفظع وأبشع ممَّن سوَّى المخلوق من تراب بمالك الرقاب، وسوَّى الذي لا يملك من الأمر شيئاً بمالك الأمرِ كلِّه، وسوَّى الناقص الفقير من جميع الوجوه بالربِّ الكامل الغنيِّ من جميع الوجوه، وسوَّى مَن لم يُنْعِمْ بمثقال ذرَّةٍ من النعم، بالذي ما بالخلق من نعمةٍ في دينهم ودنياهم وأخراهم وقلوبهم وأبدانهم إلاَّ منه، ولا يصرف السوء إلاَّ هو؛ فهل أعظم من هذا الظلم شيءٌ؟!","en":"\"And when Luqman said to his son while he was admonishing him\": admonition is command and prohibition joined with encouragement and warning; he commanded him to be sincere and forbade shirk and gave him the reason: \"Indeed, shirk is a great injustice\". Its greatness lies in nothing being more terrible than equating a creature made from dust with the Lord of all necks, equating one who owns nothing of the matter with the Owner of the whole matter, equating the deficient and needy in every respect with the perfect, self-sufficient Lord, and equating one who never gave the weight of an atom of favour with Him from whom comes every favour in people's religion, worldly life, hereafter, hearts and bodies, and who alone averts harm. Is there any injustice greater than this?"}},{"id":"luq14","ch":"luqman","t":"وصية الله بالوالدين","r":[31,14,15],"n":"وصّى الله الإنسان بوالديه، وذكر حمل الأم ومشقتها وفطامه في عامين، وأمر بشكره وشكرهما، وبمصاحبتهما في الدنيا معروفاً ولو جاهدا على الشرك، مع عدم طاعتهما فيه.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":31,"ay":14,"x":"ولما أمر بالقيام بحقِّه بترك الشرك الذي من لوازمه القيام بالتوحيد؛ أمر بالقيام بحقِّ الوالدين، فقال:{ووصَّيۡنا الإنسان}؛ أي: عهدنا إليه وجعلناه وصيةً عنده سنسأله عن القيام بها وهل حَفِظَها أم لا؟ فوصيناه {بوالديه}، وقلنا له:{اشكُرۡ لي}: بالقيام بعبوديَّتي وأداء حقوقي وأنْ لا تستعينَ بنعمي على معصيتي {ولوالديك}: بالإحسان إليهما بالقول الليِّن والكلام اللطيف والفعل الجميل والتواضع لهما وإكرامهما وإجلالهما والقيام بمؤونتهما واجتناب الإساءة إليهما من كلِّ وجه بالقول والفعل، فوصيناه بهذه الوصية وأخبرناه أنَّ {إليَّ المصيرُ}؛ أي: سترجع أيُّها الإنسان إلى من وصَّاك وكلَّفك بهذه الحقوق، فيسألك: هل قمتَ بها فيثيبك الثواب الجزيل، أم ضيَّعْتها فيعاقبك العقاب الوبيل؟!","en":"After commanding the upholding of His right by abandoning shirk, which necessitates upholding tawhid, He commanded upholding the right of parents, saying \"And We have enjoined upon man\": We entrusted him and made it a charge with him for which We will question him whether he kept it or not. We enjoined him \"concerning his parents\" and said to him \"Be grateful to Me\": by upholding My servitude, fulfilling My rights and not using My favours to disobey Me; \"and to your parents\": by kindness to them in gentle speech, courteous words and good deeds, humility toward them, honouring and revering them, bearing their expenses and avoiding harming them in every way in word and deed. We enjoined him with this counsel and informed him that \"to Me is the final destination\": you will return, O man, to the One who enjoined and charged you with these rights, and He will ask whether you fulfilled them and reward you abundantly, or neglected them and punish you severely."}},{"id":"luq16","ch":"luqman","t":"مراقبة الله في الصغير والكبير","r":[31,16],"n":"ولو كان العمل مثقال حبة من خردل في صخرة أو في السماوات أو في الأرض يأتِ بها الله، إن الله لطيف خبير.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":31,"ay":16,"x":"{يا بنيَّ إنَّها إن تَكُ مثقالَ حبةٍ من خردلٍ}: التي هي أصغرُ الأشياء وأحقرُها {فتكن في صخرةٍ}؛ أي: في وسطها، {أو في السمواتِ أو في الأرض}: في أيِّ جهة من جهاتهما؛ {يأتِ بها اللهُ}: لسعةِ علمِهِ وتمامِ خبرتِهِ وكمال قدرتِهِ، ولهذا قال:{إنَّ الله لطيفٌ خبيرٌ}؛ أي: لطف في علمه وخبرته، حتى اطَّلع على البواطن والأسرار وخفايا القفار والبحار. والمقصودُ من هذا الحثُّ على مراقبة الله والعمل بطاعته مهما أمكن، والترهيبُ من عمل القبيح قلَّ أو كَثُرَ.","en":"\"O my son, indeed if it should be the weight of a mustard seed\", the smallest and most insignificant of things, \"and should be within a rock\", in its middle, \"or in the heavens or in the earth\", in whichever direction of them, \"Allah will bring it forth\", by the vastness of His knowledge, completeness of His awareness and perfection of His power; so He said \"Indeed, Allah is Subtle, All-Aware\", subtle in His knowledge and awareness until He knows the inner depths, secrets and hidden corners of wastelands and seas. The aim is to urge mindfulness of Allah and obedience to Him as far as possible, and to warn against doing wrong, small or great."}},{"id":"luq17","ch":"luqman","t":"الصلاة والأمر بالمعروف والصبر","r":[31,17],"n":"إقامة الصلاة، والأمر بالمعروف والنهي عن المنكر، والصبر على ما يصيب الداعي، وأن ذلك من عزم الأمور.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":31,"ay":17,"x":"{يا بنيَّ أقِمِ الصَّلاة}: حثَّه عليها وخصَّها لأنَّها أكبرُ العبادات البدنيَّة، {وأمُرۡ بالمعروفِ وانۡهَ عن المنكرِ}: وذلك يستلزم العلم بالمعروف؛ ليأمر به، والعلم بالمنكر؛ لينهى عنه، والأمر بما لا يتمُّ الأمر بالمعروف، والنهي عن المنكر إلاَّ به، من الرفق والصبر، وقد صرَّح به في قوله:{واصۡبِرۡ على ما أصابك}: ومن كونه فاعلاً لما يأمر به، كافًّا لما يُنهى عنه، فتضمَّن هذا تكميلَ نفسه بفعل الخير وترك الشر، وتكميلَ غيره بذلك بأمره ونهيه. ولمَّا عُلِمَ أنَّه لا بدَّ أن يُبتلى إذا أمر ونهى وأنَّ في الأمر والنهي مشقَّة على النفوس؛ أمره بالصبر على ذلك، فقال:{واصبِرۡ على ما أصابَكَ إنَّ ذلك}: الذي وَعَظَ به لقمانُ ابنَه {من عزم الأمورِ}؛ أي: من الأمور التي يُعْزَمُ عليها، ويهتمُّ بها، ولا يوفَّق لها إلا أهلُ العزائم.","en":"\"O my son, establish prayer\": he urged him to it and singled it out because it is the greatest bodily act of worship; \"and enjoin what is right and forbid what is wrong\": that requires knowing what is right in order to enjoin it and what is wrong in order to forbid it, and requires what enjoining and forbidding cannot be complete without, such as gentleness and patience, as he made explicit in \"and be patient over what befalls you\", and also being one who does what he enjoins and refrains from what he forbids. This includes perfecting himself by doing good and leaving evil, and perfecting others by his enjoining and forbidding. Since it is known that one who enjoins and forbids will inevitably be tried, and that enjoining and forbidding is burdensome to souls, he commanded him to be patient, saying \"Indeed, that which Luqman admonished his son with is of the matters requiring resolve\": matters one resolves upon and cares about, which only people of resolve are granted."}},{"id":"luq18","ch":"luqman","t":"التواضع وخفض الصوت","r":[31,18,19],"n":"النهي عن تصعير الخد للناس وعن المشي في الأرض مرحاً، والأمر بالقصد في المشي وغضّ الصوت.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":31,"ay":18,"x":"{ولا تُصَعِّرۡ خدَّك للناس}؛ أي: لا تُمِلْهُ وتعبسْ بوجهك للناس تكبُّراً عليهم وتعاظماً، {ولا تَمۡشِ في الأرض مَرَحاً}؛ أي: بَطِراً فخراً بالنعم ناسياً المنعِم معجباً بنفسك. {إنَّ الله لا يحبُّ كلَّ مختالٍ}: في نفسه وهيئته وتعاظُمه {فخورٍ}: بقوله.","en":"\"And do not turn your cheek away from people\", that is, do not tilt it and frown at people in arrogance and self-importance, \"and do not walk upon the earth exultantly\", that is, in pride and boasting over favours, forgetting the Giver of favours and admiring yourself. \"Indeed, Allah does not like everyone self-deluded\", in himself, appearance and self-importance, \"and boastful\": in his speech."}},{"id":"nisa131","ch":"ibada","t":"وصية الله للأولين والآخرين: اتقوا الله","r":[4,131],"n":"نصّت الآية أن الله وصّى الذين أوتوا الكتاب من قبلنا وإيانا بتقوى الله، وأنه سبحانه له ما في السماوات وما في الأرض وهو الغني الحميد.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":131,"x":"يخبر تعالى عن عموم ملكه العظيم الواسع المستلزم تدبيره بجميع أنواع التَّدبير وتصرُّفه بأنواع التصريف قدراً وشرعاً؛ فتصرُّفه الشرعي أن وصَّى الأوَّلين والآخرين أهل الكتب السابقة واللاَّحقة بالتَّقوى المتضمِّنة للأمر والنَّهي وتشريع الأحكام والمجازاة لمن قام بهذه الوصيَّة بالثواب والمعاقبة لمن أهملها وضيَّعها بأليم العذاب …","en":"He informs of the vastness of His great and wide dominion, which necessitates His managing it with every kind of management and disposing it with every kind of disposal, in decree and in law; His legislative disposal is that He enjoined the first and the last, the people of earlier and later books, with piety, which includes command, prohibition, legislating rulings and recompensing those who uphold this counsel with reward and those who neglect and lose it with painful punishment …"}},{"id":"baq21","ch":"ibada","t":"اعبدوا ربكم","r":[2,21,22],"n":"نداء لجميع الناس أن يعبدوا ربهم الذي خلقهم والذين من قبلهم لعلهم يتقون، وهو الذي جعل لهم الأرض فراشاً والسماء بناء فلا يجعلوا لله أنداداً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":21,"x":"هذا أمر عام لجميع الناس بأمر عام وهو العبادة الجامعة لامتثال أوامر الله واجتناب نواهيه وتصديق خبره، فأمرهم تعالى بما خلقهم له، قال تعالى:{وما خلقت الجن والإنس إلا ليعبدون}؛ ثم استدل على وجوب عبادته وحده بأنه ربكم الذي رباكم بأصناف النعم، فخلقكم بعد العدم، وخلق الذين من قبلكم.","en":"This is a general command to all people to a general act, namely the comprehensive worship that includes obeying Allah's commands, avoiding His prohibitions and believing His reports. He commanded them to do what He created them for; the Exalted said \"And I did not create the jinn and mankind except to worship Me\". Then He gave proof for the obligation of worshipping Him alone: that He is your Lord who nurtured you with all kinds of favours, created you after non-existence, and created those before you."}},{"id":"shura13","ch":"ibada","t":"أقيموا الدين ولا تتفرقوا فيه","r":[42,13],"n":"شرع الله لنا من الدين ما وصّى به نوحاً والذي أوحاه إلى محمد وما وصّى به إبراهيم وموسى وعيسى: أن أقيموا الدين ولا تتفرقوا فيه.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":42,"ay":13,"x":"ولهذا قال:{أنۡ أقيموا الدِّين}؛ أي: أمركم أن تقيموا جميعَ شرائع الدِّين أصوله وفروعه؛ تقيمونه بأنفسكم، وتجتهدون في إقامته على غيركم، وتعاونون على البرِّ والتَّقوى، ولا تعاونون على الإثم والعدوان، {ولا تتفرَّقوا فيه}؛ أي: ليحصل منكم الاتِّفاق على أصول الدين وفروعه، واحرصوا على أن لا تفرِّقَكم المسائل وتحزِّبَكم أحزاباً، فتكونون شيعاً يعادي بعضُكم بعضاً مع اتِّفاقكم على أصل دينكم. ومن أنواع الاجتماع على الدين وعدم التفرق فيه ما أمر به الشارعُ من الاجتماعات العامَّة؛ كاجتماع الحجِّ والأعياد والجُمَع والصَّلوات الخمس والجهاد وغير ذلك من العبادات التي لا تتمُّ ولا تَكْمُلُ إلاَّ بالاجتماع لها وعدم التفرُّق.","en":"Hence He said \"that you establish the religion\": He commanded you to establish all the laws of the religion, its fundamentals and branches, establishing it yourselves, striving to establish it among others, cooperating in righteousness and piety and not cooperating in sin and aggression; \"and do not be divided therein\": so that you agree on the fundamentals and branches of the religion, and take care that issues do not divide you and split you into factions, becoming sects that oppose one another although you agree on the root of your religion. Among the forms of unity upon the religion and not dividing in it is what the Lawgiver commanded of general gatherings, such as the gathering of Hajj, the festivals, Fridays, the five prayers and jihad, and other acts of worship that are neither complete nor perfect except by gathering for them and not dividing."}},{"id":"baq238","ch":"ibada","t":"المحافظة على الصلوات","r":[2,238,239],"n":"الأمر بالمحافظة على الصلوات والصلاة الوسطى والقيام لله قانتين، وبذكر الله إذا أُمنّا كما علّمنا ما لم نكن نعلم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":238,"x":"يأمر تعالى بالمحافظة {على الصلوات}؛ عموماً وعلى، {الصلاة الوسطى}؛ وهي العصر خصوصاً، والمحافظة عليها أداؤها بوقتها وشروطها وأركانها وخشوعها وجميعِ ما لها من واجب ومستحب. وبالمحافظة على الصلوات تحصل المحافظة على سائر العبادات وتفيد النهيَ عن الفحشاء والمنكر، خصوصاً إذا أكملها كما أمر بقوله:{وقوموا لله قانتين}؛ أي: ذليلين مخلصين خاشعين، فإن القنوت دوام الطاعة مع الخشوع.","en":"The Exalted commands guarding \"the prayers\" in general and \"the middle prayer\", which is the afternoon prayer, in particular; guarding them means performing them at their time, with their conditions, pillars, humility and everything obligatory and recommended in them. By guarding the prayers, guarding all other acts of worship is achieved, and prayer forbids immorality and wrongdoing, especially when one perfects it as commanded by His words \"and stand before Allah devoutly\", meaning humble, sincere and submissive, for devoutness is continuous obedience with humility."}},{"id":"ahzab41","ch":"ibada","t":"ذكر الله كثيراً","r":[33,41,42],"n":"نداء للمؤمنين أن يذكروا الله ذكراً كثيراً ويسبحوه بكرة وأصيلاً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":33,"ay":41,"x":"يأمر تعالى المؤمنين بذكره ذكراً كثيراً؛ من تهليل وتحميد وتسبيح وتكبير وغير ذلك من كل قولٍ فيه قُربة إلى الله، وأقلُّ ذلك أن يلازِمَ الإنسان أوراد الصباح والمساء وأدبار الصلوات الخمس وعند العوارضِ والأسباب، وينبغي مداومة ذلك في جميع الأوقات على جميع الأحوال؛ فإنَّ ذلك عبادةٌ يسبِقُ بها العامل وهو مستريحٌ وداعٍ إلى محبة الله ومعرفتِهِ وعونٌ على الخير وكفٌّ للسان عن الكلام القبيح.","en":"The Exalted commands the believers to remember Him much, by tahlil, tahmid, tasbih, takbir and every statement that brings nearness to Allah; the least of that is for a person to keep to the morning and evening adhkar, those after the five prayers and at occasions and causes, and it is fitting to persist in it at all times and in all conditions, for it is an act of worship in which the doer gets ahead while resting, a call to the love and knowledge of Allah, a help to good, and a restraint of the tongue from foul speech."}},{"id":"baq152","ch":"ibada","t":"الذكر والشكر وترك الكفران","r":[2,152],"n":"اذكروني أذكركم، واشكروا لي ولا تكفرون.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":152,"x":"{فاذكروني أذكركم}؛ فأمر تعالى بذكره، ووعد عليه أفضل جزاء وهو ذكره؛ لمن ذكره كما قال تعالى على لسان رسوله:«من ذكرني في نفسه ذكرته في نفسي، ومن ذكرني في ملأ ذكرته في ملأ خير منهم» ، وذكر الله تعالى أفضله ما تواطأ عليه القلب واللسان وهو [الذكرُ] الذي يثمر معرفة الله ومحبته وكثرة ثوابه، والذكر هو رأس الشكر فلهذا أمر به خصوصاً ثم من بعده أمر بالشكر عموماً فقال:{واشكروا لي}؛ أي: على ما أنعمت عليكم بهذه النعم ودفعت عنكم صنوف النقم، والشكر يكون بالقلب إقراراً بالنعم واعترافاً، وباللسان ذكراً وثناءً، وبالجوارح طاعةً لله وانقياداً لأمره واجتناباً لنهيه، فالشكر فيه بقاء النعمة الموجودة وزيادة في النعم المفقودة، قال تعالى:{لئن شكرتم لأزيدنكم}.","en":"\"So remember Me; I will remember you\": He commanded His remembrance and promised the best reward for it, which is His remembering the one who remembers Him, as He said through His Messenger: \"Whoever remembers Me within himself, I remember him within Myself, and whoever remembers Me in a gathering, I remember him in a gathering better than it\". The best remembrance of Allah is that in which heart and tongue agree, the remembrance that bears knowledge of Allah, love of Him and abundant reward. Remembrance is the head of gratitude, so He commanded it specifically, then after it commanded gratitude in general, saying \"and be grateful to Me\" for the favours He bestowed and the afflictions He averted. Gratitude is by the heart through acknowledging favours, by the tongue through mention and praise, and by the limbs through obedience to Allah, submission to His command and avoiding His prohibition. In gratitude lies the preservation of existing favour and the increase of lost favour; the Exalted said \"If you are grateful, I will surely increase you\"."}},{"id":"ali200","ch":"ibada","t":"الصبر والمصابرة والمرابطة والتقوى","r":[3,200],"n":"يا أيها الذين آمنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":3,"ay":200,"x":"ثم حض المؤمنين على ما يوصلهم إلى الفلاح، وهو الفوز بالسعادة والنجاح، وأن الطريق الموصل إلى ذلك لزوم الصبر: الذي هو حبس النفس على ما تكرهه من ترك المعاصي ومن الصبر على المصائب وعلى الأوامر الثقيلة على النفوس، فأمرهم بالصبر على جميع ذلك. والمصابرة: هي الملازمة والاستمرار على ذلك على الدوام، ومقاومة الأعداء في جميع الأحوال. والمرابطة: وهو لزوم المحل الذي يُخاف من وصول العدو منه وأن يراقبوا أعداءهم ويمنعوهم من الوصول إلى مقاصدهم، لعلهم يفلحون: يفوزون بالمحبوب الديني والدنيوي والأخروي وينجون من المكروه كذلك. فعلم من هذا أنه لا سبيل إلى الفلاح بدون الصبر والمصابرة والمرابطة المذكورات، فلم يفلح مَنْ أفلح إلا بها ولم يفت أحداً الفلاحُ إلا بالإخلال بها أو ببعضها.","en":"Then He urged the believers to what leads them to success, which is achieving happiness and triumph, and that the way leading to it is holding fast to patience, which is restraining the soul from what it dislikes: abandoning sins, enduring calamities and enduring commands heavy on souls; so He commanded them to be patient in all of that. Perseverance is constancy and continuing in it permanently and resisting enemies in all conditions. Vigilance is staying in the place from which enemy approach is feared, watching enemies and preventing them from reaching their aims, so that perhaps they succeed, that is, attain the religious, worldly and heavenly object of love and are saved from the disliked likewise. It is known from this that there is no way to success without the patience, perseverance and vigilance mentioned; whoever succeeded succeeded only by them, and no one missed success except by neglecting them or some of them."}},{"id":"ali102","ch":"ibada","t":"اتقوا الله حق تقاته واعتصموا بحبله","r":[3,102,103],"n":"الأمر بتقوى الله حق تقاته وأن لا نموت إلا مسلمين، والاعتصام بحبل الله جميعاً وعدم التفرق، وذكر نعمة الله بالتأليف بين القلوب.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":3,"ay":102,"x":"هذه الآيات فيها حث الله عباده المؤمنين أن يقوموا بشكر نعمه العظيمة بأن يتقوه حق تقواه، وأن يقوموا بطاعته وترك معصيته مخلصين له بذلك، وأن يقيموا دينهم ويستمسكوا بحبله الذي أوصله إليهم، وجعله السبب بينهم وبينه وهو دينه وكتابه، والاجتماع على ذلك وعدم التفرق، وأن يستديموا ذلك إلى الممات. وذكرهم ما هم عليه قبل هذه النعمة وهو أنهم كانوا أعداء متفرقين فجمعهم بهذا الدين وألّف بين قلوبهم وجعلهم إخواناً، وكانوا على شفا حفرة من النار فأنقذهم من الشقاء، ونهج بهم طريق السعادة؛ لذلك بين {الله لكم آياته لعلكم تهتدون}؛ إلى شكر الله والتمسك بحبله.","en":"These verses urge the believers to thank Allah for His great favours by fearing Him as He should be feared, upholding obedience to Him and leaving disobedience sincerely, establishing their religion and holding fast to His rope which He connected to them and made the link between them and Him, namely His religion and book, uniting upon it and not dividing, and persisting in that until death. He reminded them of their state before this favour, that they were scattered enemies, so He united them by this religion, joined their hearts and made them brothers, while they were on the brink of a pit of Fire and He saved them from wretchedness and led them to the path of happiness; therefore \"Allah makes clear to you His verses that you may be guided\", to thankfulness to Allah and holding fast to His rope."}},{"id":"nisa11","ch":"usra","t":"يوصيكم الله في أولادكم","r":[4,11],"n":"افتتح الله آية المواريث بقوله «يوصيكم الله في أولادكم»، ثم بيّن أنصبة الأولاد والوالدين، وأن ذلك من بعد وصية يوصى بها أو دين، فريضة من الله.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":11,"x":"فقوله تعالى: {يوصيكم الله في أولادكم}؛ أي: أولادكم يا معشر الوالدين عندكم ودائع قد وصاكم الله عليهم لتقوموا بمصالحهم الدينيَّة والدنيويَّة، فتعلِّمونهم وتؤدِّبونهم وتكفُّونهم عن المفاسد وتأمرونَهم بطاعة الله وملازمة التقوى على الدوام؛ كما قال تعالى:{يا أيُّها الذين آمنوا قوا أنفسكم وأهليكم ناراً وَقودها الناس والحجارةُ}؛ فالأولاد عند والِديهم موصىً بهم؛ فإمَّا أن يقوموا بتلك الوصية؛ فلهم جزيل الثواب، وإمَّا أن يضيِّعوها؛ فيستحقوا بذلك الوعيد والعقاب. وهذا مما يدلُّ على أن الله تعالى أرحم بعباده من الوالِدينِ، حيث أوصى الوالِدينِ مع كمال شفقتهم عليهم.","en":"His words \"Allah instructs you concerning your children\": that is, your children, O parents, are with you as trusts that Allah has charged you with, to look after their religious and worldly interests, so you teach them, discipline them, restrain them from corruption, command them to obey Allah and to keep piety continually, as the Exalted said \"O you who believe, protect yourselves and your families from a Fire whose fuel is people and stones\". Children are thus entrusted to their parents by counsel: either they uphold that counsel and have abundant reward, or neglect it and deserve warning and punishment. This shows that Allah is more merciful to His servants than parents are, since He gave parents a counsel despite their perfect compassion for their children."}},{"id":"ahqaf15","ch":"usra","t":"وصية الله بالوالدين وشكر النعمة","r":[46,15],"n":"وصّى الله الإنسان بوالديه إحساناً، وذكر حمل أمه ووضعها له كرهاً وأن حمله وفصاله ثلاثون شهراً، ودعاء من بلغ أربعين سنة أن يوزعه الله شكر نعمته وأن يصلح له في ذريته.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":46,"ay":15,"x":"هذا من لطفه تعالى بعباده وشكره للوالدين أن وصَّى الأولاد وعهد إليهم أن يحسنوا إلى والديهم بالقول اللطيف والكلام الليِّن وبَذْل المال والنفقة وغير ذلك من وجوه الإحسان، ثم نبَّه على ذكر السبب الموجب لذلك، فذكر ما تحمَّلته الأمُّ من ولدها، وما قاستْه من المكاره وقت حَمْلِها، ثم مشقَّة ولادتها المشقَّة الكبيرة، ثم مشقَّة الرضاع وخدمة الحضانة، وليست المذكوراتُ مدة يسيرة ساعة أو ساعتين، وإنما ذلك مدة طويلة قدرها {ثلاثون شهراً}: للحمل تسعة أشهر ونحوها، والباقي للرضاع، هذا الغالب.","en":"This is from His kindness to His servants and His appreciation of parents: He enjoined children and entrusted them to treat their parents well, with gentle speech, soft words, spending money and maintenance and other forms of kindness. Then He pointed out the reason requiring it, recalling what the mother bore for her child and the hardship she endured during pregnancy, then the great hardship of labour, then the hardship of nursing and the care of raising; and these are not a brief time of an hour or two but a long period of \"thirty months\", nine months or so for pregnancy and the rest for nursing, which is the usual case."}},{"id":"ankabut8","ch":"usra","t":"برّ الوالدين وحدّه عند الشرك","r":[29,8],"n":"وصّى الله الإنسان بوالديه حسناً، فإن جاهداه ليشرك به ما ليس له به علم فلا يطعهما، وإلى الله مرجع الجميع.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":29,"ay":8,"x":"أي: وأمرنا الإنسان ووصَّيْناه بوالديه حُسناً؛ أي: ببرِّهما والإحسان إليهما بالقول والعمل، وأن يحافظَ على ذلك ولا يعقهما ويسيء إليهما في قوله وعمله، {وإن جاهداك} على أن تشرك {بي ما ليسَ لك به علمٌ}: وليس لأحدٍ علمٌ بصحَّة الشرك بالله، وهذا تعظيمٌ لأمر الشرك. {فلا تُطِعۡهُما إليَّ مرجِعُكم فأنبِّئُكُم بما كنتُم تعملونَ}: فأجازيكم بأعمالكم؛ فبرُّوا والديكم، وقدِّموا طاعتهما إلاَّ على طاعة الله ورسوله؛ فإنَّها مقدَّمة على كل شيء.","en":"That is: We commanded man and enjoined him concerning his parents with goodness, that is, to be dutiful to them and kind to them in word and deed, to keep to that, and not to disobey them or wrong them in word or deed; \"and if they strive with you to make you associate with Me that of which you have no knowledge\": no one has any knowledge of the soundness of shirk, and this magnifies the matter of shirk; \"do not obey them. To Me is your return, and I will inform you of what you used to do\": so I will recompense you for your deeds. So be dutiful to your parents and give priority to obeying them, except over obedience to Allah and His Messenger, which takes precedence over everything."}},{"id":"baq132","ch":"usra","t":"وصية إبراهيم ويعقوب لبنيهما","r":[2,132,133],"n":"وصّى بها إبراهيم بنيه ويعقوب: «يا بنيّ إن الله اصطفى لكم الدين فلا تموتن إلا وأنتم مسلمون»، وسأل يعقوب بنيه عند موته ما تعبدون من بعدي.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":132,"x":"{يا بني إن الله اصطفى لكم الدين}؛ أي: اختاره، وتخيره لكم رحمة بكم وإحساناً إليكم، فقوموا به، واتصفوا بشرائعه، وانصبغوا بأخلاقه حتى تستمروا على ذلك فلا يأتيكم الموت إلا وأنتم عليه، لأن من عاش على شيء مات عليه، ومن مات على شيء بعث عليه.","en":"\"O my sons, indeed Allah has chosen for you this religion\": He selected it and picked it for you out of mercy and kindness to you, so uphold it, be characterised by its laws and take on the colour of its character until you continue upon that and death comes to you only while you are upon it, for whoever lives on something dies on it, and whoever dies on something is resurrected upon it."}},{"id":"taha132","ch":"usra","t":"وأمر أهلك بالصلاة","r":[20,132],"n":"أمر الله نبيه أن يأمر أهله بالصلاة ويصطبر عليها، وبيّن أنه لا يسأله رزقاً وهو يرزقه، والعاقبة للتقوى.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":20,"ay":132,"x":"أي: حُثَّ أهلك على الصلاة، وأزْعِجْهم إليها من فرض ونفل، والأمرُ بالشيء أمرٌ بجميع ما لا يتمُّ إلاَّ به، فيكون أمراً بتعليمهم ما يُصْلِحُ الصلاة ويفسِدُها ويُكْمِلُها. {واصۡطَبِرۡ عليها}؛ أي: على الصلاة بإقامتها بحدودها وأركانها [وآدابها] وخشوعها؛ فإنَّ ذلك مشقٌّ على النفس، ولكنْ ينبغي إكراهها وجهادُها على ذلك والصبر معها دائماً؛ فإنَّ العبد إذا أقام صلاته على الوجه المأمور به؛ كان لما سِواها من دينِهِ أحفظَ وأقوم، وإذا ضيَّعها؛ كان لما سِواها أضيعَ.","en":"That is: urge your family to prayer and stir them to it, obligatory and voluntary; commanding something is commanding everything it cannot be completed without, so it is a command to teach them what makes prayer sound, invalid and complete. \"And be steadfast therein\": by establishing it with its limits, pillars, [etiquette] and humility, for that is hard on the soul, yet one should compel it and strive with it and be patient with it always; for when a servant establishes his prayer as commanded, he is more protective and upright regarding the rest of his religion, and if he neglects it, he is more negligent of everything else."}},{"id":"tahrim6","ch":"usra","t":"قوا أنفسكم وأهليكم ناراً","r":[66,6],"n":"خطاب للمؤمنين أن يقوا أنفسهم وأهليهم ناراً وقودها الناس والحجارة، عليها ملائكة غلاظ شداد لا يعصون الله ما أمرهم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":66,"ay":6,"x":"قوموا بلوازمه وشروطه، فَـ {قُوا أنفسكم وأهليكم ناراً} موصوفةً بهذه الأوصاف الفظيعة، ووقاية الأنفس بإلزامها أمر الله امتثالاً ونهيه اجتناباً والتوبة عمَّا يُسْخِطُ الله ويوجب العذاب، ووقاية الأهل والأولاد بتأديبهم وتعليمهم وإجبارهم على أمر الله؛ فلا يسلم العبد إلاَّ إذا قام بما أمر الله به في نفسه وفيمن تحت ولايته من الزوجات والأولاد وغيرهم ممَّن هم تحت ولايته وتصرُّفه …","en":"Uphold its requirements and conditions, and \"protect yourselves and your families from a Fire\" described with these terrible descriptions; protecting oneself is by holding oneself to Allah's command in compliance and His prohibition in avoidance and repenting of what angers Allah and brings punishment, and protecting family and children is by disciplining them, teaching them and obliging them to Allah's command; so a servant is safe only if he upholds what Allah commanded in himself and in those under his charge, of wives, children and others who are under his authority and control …"}},{"id":"nisa19","ch":"usra","t":"وعاشروهن بالمعروف","r":[4,19],"n":"نهي عن إرث النساء كرهاً وعن عضلهن، وأمر بمعاشرتهن بالمعروف، فإن كرهوهن فعسى أن يكرهوا شيئاً ويجعل الله فيه خيراً كثيراً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":19,"x":"ثم قال:{وعاشروهنَّ بالمعروف}: وهذا يشمل المعاشرةَ القوليَّة والفعليَّة، فعلى الزوج أن يعاشر زوجته بالمعروف من الصحبة الجميلة وكفِّ الأذى وبذل الإحسان وحسن المعاملة، ويدخل في ذلك النفقة والكسوة ونحوهما، فيجب على الزوج لزوجته المعروف من مثلِهِ لمثلها في ذلك الزمان والمكان، وهذا يتفاوت بتفاوت الأحوال. {فإن كرهتموهنَّ فعسى أن تكرهوا شيئاً ويجعلَ الله فيه خيراً كثيراً}؛ أي: ينبغي لكم أيها الأزواج أن تُمْسِكوا زوجاتِكم مع الكراهة لهنَّ؛ فإنَّ في ذلك خيراً كثيراً: من ذلك امتثالُ أمر الله وقَبولُ وصيَّته التي فيها سعادة الدنيا والآخرة.","en":"Then He said: \"and live with them in kindness\": this includes kindness in word and deed; the husband must live with his wife in kindness, with good companionship, restraining harm, giving kindness and good treatment, including maintenance, clothing and the like, so the husband owes his wife what is customary for one like him toward one like her in that time and place, which varies with conditions. \"And if you dislike them, perhaps you dislike a thing and Allah makes therein much good\": that is, you husbands should keep your wives despite disliking them, for in that is much good, among it compliance with Allah's command and acceptance of His counsel, in which lies the happiness of this world and the next."}},{"id":"ahzab70","ch":"akhlaq","t":"اتقوا الله وقولوا قولاً سديداً","r":[33,70,71],"n":"تقوى الله والقول السديد سبب لإصلاح الأعمال ومغفرة الذنوب، ومن يطع الله ورسوله فقد فاز فوزاً عظيماً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":33,"ay":70,"x":"يأمر تعالى المؤمنين بتقواه في جميع أحوالِهِم في السرِّ والعلانية، ويخصُّ منها ويندب للقول السديد، وهو القول الموافق للصواب أو المقارب له عند تعذُّر اليقين من قراءةٍ وذكرٍ وأمرٍ بمعروف ونهي عن منكر وتعلُّم علم وتعليمه والحرص على إصابة الصواب في المسائل العلميَّة وسلوك كلِّ طريق موصِل لذلك وكل وسيلةٍ تُعين عليه.","en":"The Exalted commands the believers to fear Him in all their conditions, in secret and in public, and singles out and urges one aspect, upright speech, which is the speech that accords with what is right or comes close to it when certainty is unavailable, whether recitation, remembrance, enjoining good and forbidding evil, learning and teaching knowledge, striving to reach the right in matters of knowledge and following every path that leads to it and every means that helps it."}},{"id":"baq83","ch":"akhlaq","t":"وقولوا للناس حسناً","r":[2,83],"n":"من ميثاق بني إسرائيل: عبادة الله وحده، والإحسان إلى الوالدين وذي القربى واليتامى والمساكين، والقول الحسن للناس، وإقامة الصلاة وإيتاء الزكاة.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":83,"x":"ثم أمر بالإحسان إلى الناس عموماً فقال:{وقولوا للناس حسناً}؛ ومن القول الحسن أمرهم بالمعروف ونهيهم عن المنكر وتعليمهم العلم وبذل السلام والبشاشة وغير ذلك من كل كلام طيب، ولما كان الإنسان لا يسع الناس بماله أُمر بأمر يقدر به على الإحسان إلى كل مخلوق وهو الإحسان بالقول، فيكون في ضمن ذلك النهي عن الكلام القبيح للناس حتى للكفار، ولهذا قال تعالى:{ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن}؛ ومن أدب الإنسان الذي أدب الله به عباده أن يكون الإنسان نزيهاً في أقواله وأفعاله، غير فاحش ولا بذيء ولا شاتم ولا مخاصم، بل يكون حسن الخلق واسع الحلم، مجاملاً لكلِّ أحد، صبوراً على ما يناله من أذى الخلق امتثالاً لأمر الله ورجاءً لثوابه.","en":"Then He commanded kindness to people in general, saying \"and speak to people good words\": good speech includes commanding them to what is right, forbidding them from what is wrong, teaching them knowledge, extending greeting and cheerfulness and every other good word. Since a person cannot reach people with his wealth, he was commanded something by which he can be kind to every creature, which is kindness in speech; this includes the prohibition of foul speech to people, even to disbelievers, hence the Exalted said \"and do not argue with the People of the Scripture except in the best way\". Part of the manners with which Allah disciplined His servants is that a person be pure in his words and deeds, not vulgar, obscene, abusive or quarrelsome, but of good character and great forbearance, courteous to everyone, patient with the harm he receives from people, in compliance with Allah's command and hope for His reward."}},{"id":"araf199","ch":"akhlaq","t":"خذ العفو وأمر بالعرف وأعرض عن الجاهلين","r":[7,199],"n":"جمعت الآية حسن الخلق: أخذ العفو وما تيسّر من أخلاق الناس، والأمر بالعرف، والإعراض عن الجاهلين.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":7,"ay":199,"x":"هذه الآية جامعة لِحُسْنِ الخلق مع الناس وما ينبغي في معاملتهم: فالذي ينبغي أن يعامَلَ به الناس: أن يأخذَ العفوَ؛ أي: ما سمحتْ به أنفسُهم وما سَهُلَ عليهم من الأعمال والأخلاق؛ فلا يكلِّفهم ما لا تسمح به طبائعهم، بل يشكُر من كلِّ أحدٍ ما قابله به من قول وفعل جميل أو ما هو دونَ ذلك، ويتجاوزُ عن تقصيرِهم ويغضُّ طرفه عن نقصهم ولا يتكبَّر على الصغير لصغره ولا ناقص العقل لنقصه ولا الفقير لفقره، بل يعامل الجميع باللُّطف والمقابلة بما تقتضيه الحال وتنشرح له صدورهم. {وأمُرۡ بالعُرۡفِ}؛ أي: بكل قول حسن وفعل جميل وخلق كامل للقريب والبعيد؛ فاجعل ما يأتي إلى الناس منك إما تعليم علم أو حث على خير من صلة رحم أو برِّ والدين أو إصلاح بين الناس أو نصيحة نافعة أو رأي مصيب أو معاونة على برٍّ وتقوى أو زجر عن قبيح أو إرشاد إلى تحصيل مصلحة دينيَّة أو دنيويَّة.","en":"This verse is comprehensive of good character with people and how one should deal with them: what is fitting is to \"accept forgiveness\", that is, what their souls offer and what comes easily to them of deeds and character, so he does not burden them with what their natures do not permit, but is thankful for what anyone offers him of good word or deed or even less, overlooks their shortcomings, turns a blind eye to their deficiencies, is not arrogant toward the small for his smallness, the weak-minded for his weakness or the poor for his poverty, but treats everyone with gentleness and as the situation requires and as their hearts find pleasant. \"And enjoin what is right\": every good word, beautiful deed and complete character for near and far; so let what reaches people from you be teaching knowledge, urging good such as upholding kinship, dutifulness to parents, reconciling people, useful advice, sound opinion, help in righteousness and piety, deterring from evil or guiding to a religious or worldly benefit."}},{"id":"fussilat34","ch":"akhlaq","t":"ادفع بالتي هي أحسن","r":[41,33,35],"n":"لا تستوي الحسنة ولا السيئة، فيُؤمر بدفع السيئة بالتي هي أحسن فإذا الذي بينك وبينه عداوة كأنه ولي حميم، وما يلقّاها إلا الذين صبروا وذو حظ عظيم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":41,"ay":34,"x":"ثم أمر بإحسان خاصٍّ، له موقعٌ كبيرٌ، وهو الإحسان إلى مَنْ أساء إليك، فقال:{ادفعۡ بالتي هي أحسنُ}؛ أي: فإذا أساء إليك مسيءٌ من الخلق، خصوصاً من له حقٌّ كبيرٌ عليك؛ كالأقارب والأصحاب ونحوهم، إساءةً بالقول أو بالفعل؛ فقابِلْه بالإحسان إليه؛ فإنْ قَطَعَكَ؛ فصِلْه، وإنْ ظلمكَ؛ فاعفُ عنه، وإن تكلَّم فيك غائباً أو حاضراً؛ فلا تقابِلْه، بل اعفُ عنه وعامِلْه بالقول الليِّن، وإن هَجَرَكَ وترك خطابك؛ فطيِّبْ له الكلام وابذلْ له السلام؛ فإذا قابلتَ الإساءة بالإحسان؛ حصل فائدةٌ عظيمةٌ. {فإذا الذي بينَك وبينَه عداوةٌ كأنَّه وليٌّ حميمٌ}؛ أي: كأنه قريبٌ شفيقٌ.","en":"Then He commanded a particular kind of kindness of great weight, which is kindness to the one who wronged you, saying \"Repel evil by that which is better\": if one of people wrongs you, especially one with a great right upon you such as relatives and companions, by word or deed, meet it with kindness to him; if he cuts you off, keep ties with him; if he wrongs you, pardon him; if he speaks of you in your absence or presence, do not retaliate but pardon him and treat him with gentle speech; and if he shuns you and leaves addressing you, sweeten your speech to him and offer him greeting. When you meet evil with kindness, a great benefit results: \"And thereupon the one between whom and you was enmity will become as though he was a devoted friend\", that is, as though he were a close, caring relative."}},{"id":"hujurat6","ch":"akhlaq","t":"التثبّت من خبر الفاسق","r":[49,6],"n":"إن جاء فاسق بنبأ فتبيّنوا لئلا تصيبوا قوماً بجهالة فتصبحوا على ما فعلتم نادمين.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":49,"ay":6,"x":"وهذا أيضاً من الآداب التي على أولي الألباب التأدُّبُ بها واستعمالها، وهو أنه إذا أخبرهم فاسقٌ بنبأ؛ أي: خبرٍ: أن يتثبَّتوا في خبره، ولا يأخذوه مجرداً؛ فإن في ذلك خطراً كبيراً ووقوعاً في الإثم؛ فإنَّ خبره إذا جُعل بمنزلة خبر الصادق العدل؛ حكم بموجب ذلك ومقتضاه، فحصل من تلف النفوس والأموال بغير حقٍّ بسبب ذلك الخبر ما يكون سبباً للندامة، بل الواجبُ عند خبر الفاسق التثبُّت والتبيُّن …","en":"This too is among the manners that people of understanding must observe and apply: when a wrongdoer brings them news, they should verify his report and not take it at face value, for there is great danger and a falling into sin in that, because if his report were treated like that of a truthful, just person, a ruling would follow from it, causing loss of lives and property without right through that report, a cause of regret; rather, the duty upon a wrongdoer's report is verification and clarification …"}},{"id":"hujurat11","ch":"akhlaq","t":"ترك السخرية واللمز والظن","r":[49,11,12],"n":"النهي عن سخرية قوم من قوم وعن اللمز والتنابز بالألقاب، وعن كثير من الظن والتجسس والغيبة.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":49,"ay":11,"x":"وهذا أيضاً من حقوق المؤمنين بعضهم على بعض؛ أن:{لا يَسۡخَرۡ قومٌ من قومٍ}: بكلِّ كلامٍ وقولٍ وفعلٍ دالٍّ على تحقير الأخ المسلم؛ فإنَّ ذلك حرامٌ لا يجوز، وهو دالٌّ على إعجاب الساخر بنفسه، وعسى أن يكون المسخورُ به خيراً من الساخر، وهو الغالبُ والواقعُ؛ فإنَّ السخرية لا تقع إلاَّ من قلب ممتلئٍ من مساوئ الأخلاق، متحلٍّ بكل خلقٍ ذميمٍ، متخلٍّ من كلِّ خلقٍ كريم، ولهذا قال النبي - صلى الله عليه وسلم -: «بحسب امرئٍ من الشرِّ أن يحقر أخاه المسلمَ». ثم قال:{ولا تَلۡمِزوا أنفُسَكُم}؛ أي: لا يعب بعضكم على بعض، واللَّمزُ بالقول، والهمز بالفعل، وكلاهما منهيٌّ عنه حرامٌ متوعَّدٌ عليه بالنار …","en":"This too is among the rights of believers over one another: that \"no people ridicule another people\", by any speech, word or deed pointing to belittling the Muslim brother, for that is forbidden and impermissible and indicates the mocker's self-admiration; perhaps the one mocked is better than the mocker, which is the usual case and the reality, for mockery arises only from a heart full of bad character, adorned with every blameworthy trait and bare of every noble one; hence the Prophet, peace be upon him, said: \"It is enough evil for a man to belittle his Muslim brother\". Then He said \"and do not defame one another\": do not find fault with one another; lamz is by speech and hamz by deed, and both are forbidden and carry the threat of Fire …"}},{"id":"nur30","ch":"akhlaq","t":"غضّ البصر وحفظ الفروج","r":[24,30,31],"n":"أمر الله المؤمنين والمؤمنات أن يغضوا من أبصارهم ويحفظوا فروجهم، وأن ذلك أزكى لهم، وأن الله خبير بما يصنعون.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":24,"ay":30,"x":"أي: أرشدِ المؤمنين وقُلْ لهم: الذين معهم إيمانٌ يمنعُهم من وقوع ما يُخِلُّ بالإيمان {يغضُّوا من أبصارِهم}: عن النظر إلى العورات وإلى النساء الأجنبيَّات وإلى المُرْدانِ، الذين يُخاف بالنظرِ إليهم الفتنة وإلى زينة الدُّنيا التي تفتنُ وتوقِعُ في المحذور. {ويحفَظُوا فروجَهم}: عن الوطء الحرام في قُبُل أو دُبُر أو ما دونَ ذلك وعن التمكين من مسِّها والنظر إليها.","en":"That is: guide the believers and tell them: those who have faith that prevents them from falling into what undermines faith should \"lower their gaze\", from looking at private parts, at unrelated women and at beardless youths, looking at whom is feared to cause temptation, and at worldly adornment that tempts and causes one to fall into what is to be avoided. \"And guard their private parts\": from unlawful intercourse in front or behind or less, and from allowing them to be touched or looked at."}},{"id":"nur27","ch":"akhlaq","t":"الاستئذان قبل دخول البيوت","r":[24,27,28],"n":"لا تدخلوا بيوتاً غير بيوتكم حتى تستأنسوا وتسلّموا على أهلها، وإن قيل لكم ارجعوا فارجعوا هو أزكى لكم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":24,"ay":27,"x":"يُرشد الباري عبادَه المؤمنين أن لا يدخُلوا بيوتاً غير بيوتهم بغيرِ استئذانٍ؛ فإنَّ في ذلك عدَّةَ مفاسدَ: منها: ما ذكرهُ الرسولُ - صلى الله عليه وسلم -: حيث قال: «إنَّما جُعِلَ الاستئذانُ من أجل البصرِ» ؛ فبسبب الإخلال به يقع البصر على العوراتِ التي داخل البيوت؛ فإنَّ البيت للإنسان في ستر عورةِ ما وراءه بمنزلة الثوبِ في ستر عورةِ جسدِهِ.","en":"The Creator guides His believing servants not to enter houses other than their own without asking permission, for in that are several evils, among them what the Messenger, peace be upon him, mentioned when he said \"Asking permission was made only because of the sight\"; by neglecting it, the eye falls upon the private matters inside homes, for a home for a person in covering what is behind it is like a garment in covering the body."}},{"id":"nisa29","ch":"mal","t":"لا تأكلوا أموالكم بينكم بالباطل","r":[4,29,30],"n":"نهي عن أكل الأموال بالباطل واستثناء التجارة عن تراضٍ، ونهي عن قتل الأنفس، رحمةً من الله بعباده.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":29,"x":"ينهى تعالى عباده المؤمنين أن يأكلوا أموالهم بينهم بالباطل، وهذا يشمل أكلَها بالغصوب والسرقات وأخذَها بالقمار والمكاسب الرديئة، بل لعله يدخل في ذلك أكل مال نفسِك على وجه البطر والإسراف؛ لأن هذا من الباطل، وليس من الحق. ثم إنه لما حرَّم أكلها بالباطل؛ أباح لهم أكلها بالتجارات والمكاسب الخالية من الموانع المشتملة على الشروط من التراضي وغيره.{ولا تقتلوا أنفسكم}؛ أي: لا يقتل بعضكم بعضاً، ولا يقتل الإنسان نفسه، ويدخل في ذلك الإلقاء بالنفس إلى التهلكة وفعل الأخطار المفضية إلى التلف والهلاك {إنَّ الله كان بكم رحيماً}: ومن رحمته أن صان نفوسَكم وأموالكم ونهاكم عن إضاعتها وإتلافها ورتَّب على ذلك ما رتَّبه من الحدود.","en":"The Exalted forbids His believing servants to consume their wealth among themselves unjustly, which includes consuming it by usurpation, theft, gambling and bad earnings; perhaps it even includes consuming one's own wealth in extravagance and waste, since that is wrongful, not right. Then, having forbidden consuming it unjustly, He permitted them to consume it by trade and earnings free of obstacles and meeting the conditions of mutual consent and other things. \"And do not kill yourselves\": that is, do not kill one another, and let no one kill himself, which includes casting oneself into destruction and committing risks leading to loss and ruin. \"Indeed, Allah is ever Merciful to you\": part of His mercy is that He protected your lives and wealth and forbade wasting and destroying them and set what He set of penalties for it."}},{"id":"riba","ch":"mal","t":"اتقوا الله وذروا ما بقي من الربا","r":[2,278,280],"n":"أمر الله المؤمنين أن يتقوه ويذروا ما بقي من الربا، ومن لم يفعل فقد أُذِّن بحرب من الله ورسوله، ولهم رؤوس أموالهم، وأمر بإنظار المعسر.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":278,"x":"{إن الذين آمنوا وعملوا الصالحات وأقاموا الصلاة وآتوا الزكاة}؛ الآية لبيان أن أكبر الأسباب لاجتناب ما حرم الله من المكاسب الربوية تكميل الإيمان وحقوقه، خصوصاً إقامة الصلاة وإيتاء الزكاة، فإن الصلاة تنهى عن الفحشاء والمنكر، والزكاة إحسان إلى الخلق ينافي تعاطي الربا الذي هو ظلم لهم وإساءة عليهم، ثم وجه الخطاب للمؤمنين وأمرهم أن يتقوه ويذروا ما بقي من معاملات الربا التي كانوا يتعاطونها قبل ذلك وأنهم إن لم يفعلوا ذلك فإنهم محارِبون لله ورسوله، وهذا من أعظم ما يدل على شناعة الربا حيث جعل المصرَّ عليه محارباً لله ورسوله، ثم قال:{وإن تبتم}؛ يعني من المعاملات الربوية {فلكم رؤوس أموالكم لا تظلمون}؛ الناس بأخذ الربا {ولا تظلمون}؛ ببخسكم رؤوس أموالكم، فكل من تاب من الربا فإن كانت معاملات سالفة فله ما سلف وأمره منظور فيه، وإن كانت معاملات موجودة وجب عليه أن يقتصر على رأس ماله، فإن أخذ زيادة فقد تجرأ على الربا.","en":"\"Indeed, those who believe, do righteous deeds, establish prayer and give zakah\": the verse explains that the greatest cause of avoiding the forbidden usurious earnings is perfecting faith and its rights, especially establishing prayer and giving zakah, for prayer forbids immorality and wrongdoing and zakah is kindness to creation, contradicting the practice of usury, which is injustice to them and harm toward them. Then He addressed the believers and commanded them to fear Him and give up what remains of the usurious dealings they used to practise before, and that if they do not do so they are waging war against Allah and His Messenger, which is among the greatest evidence of the abomination of usury, since He made the one who persists in it a warrior against Allah and His Messenger. Then He said \"And if you repent\", that is, from usurious dealings, \"you may have your principal, not wronging\", people by taking usury, \"and not being wronged\", by loss of your principal. So whoever repents of usury, if the dealings were past, he keeps what is past and his matter is left to Allah; if dealings are ongoing he must restrict himself to his capital, and if he takes an increase he has dared to take usury."}},{"id":"dayn","ch":"mal","t":"كتابة الدين والإشهاد عليه","r":[2,282],"n":"أمر الله إذا تداينتم بدين إلى أجل مسمى بكتابته بالعدل، وأن لا يأبى الكاتب، وأن يملّ الذي عليه الحق وليتق الله ولا يبخس، وبالإشهاد.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":282,"x":"ومنها: أمره تعالى بكتابة الديون، وهذا الأمر قد يجب إذا وجب حفظ الحق كالذي للعبد عليه ولاية، كأموال اليتامى والأوقاف والوكلاء والأمناء، وقد يقارب الوجوب كما إذا كان الحق متمحضاً للعبد فقد يقوى الوجوب وقد يقوى الاستحباب، بحسب الأحوال المقتضية لذلك، وعلى كل حال فالكتابة من أعظم ما تحفظ به هذه المعاملات المؤجلة لكثرة النسيان ولوقوع المغالطات، وللاحتراز من الخونة الذين لا يخشون الله تعالى. ومنها: أمره تعالى للكاتب أن يكتب بين المتعاملين بالعدل فلا يميل مع أحدهما لقرابة ولا غيرها ولا على أحدهما لعداوة ونحوها. ومنها: أن الكتابة بين المتعاملين من أفضل الأعمال ومن الإحسان إليهما، وفيها حفظ حقوقهما وبراءة ذممهما كما أمره الله بذلك فليحتسب الكاتب بين الناس هذه الأمور ليحظى بثوابها.","en":"Among them: His command to write down debts. This command may be obligatory when preserving a right is obligatory, such as what a person holds in guardianship, like orphans' property, endowments, agents and trustees; it may approach obligation, as when the right belongs purely to an individual, and the obligation may be strong or the recommendation strong according to the circumstances. In every case writing is among the greatest means of preserving these deferred dealings because of frequent forgetfulness, the occurrence of false claims and to guard against traitors who do not fear Allah. Among them: His command to the scribe to write between the parties with justice, not inclining toward one because of kinship or otherwise nor against one out of enmity and the like. Among them: that writing between the parties is among the best deeds and a kindness to both, preserving their rights and clearing their obligations as Allah commanded him, so let the scribe seek reward in this among people."}},{"id":"uqud","ch":"mal","t":"أوفوا بالعقود","r":[5,1],"n":"يا أيها الذين آمنوا أوفوا بالعقود، وهي أمر بالوفاء بكل ما التزمه المؤمن مع ربه ومع الناس.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":5,"ay":1,"x":"هذا أمر من الله تعالى لعباده المؤمنين بما يقتضيه الإيمان بالوفاء بالعقود؛ أي: بإكمالها وإتمامها وعدم نقضها ونقصها، وهذا شامل للعقود التي بين العبد وبين ربِّه من التزام عبوديته؛ والقيام بها أتم قيام، وعدم الانتقاص من حقوقها شيئاً، والتي بينه وبين الرسول بطاعته واتباعه، والتي بينه وبين الوالدين والأقارب ببرِّهم وصلتهم وعدم قطيعتهم، والتي بينه وبين أصحابه من القيام بحقوق الصحبة في الغنى والفقر واليسر والعسر، والتي بينه وبين الخلق من عقود المعاملات كالبيع والإجارة ونحوهما …","en":"This is a command from Allah to His believing servants, in what faith requires, to fulfil contracts, that is, to complete them and not break or reduce them. It includes the contracts between the servant and his Lord, taking on His servitude and upholding it perfectly without diminishing any of its rights; those between him and the Messenger through obeying and following him; those between him and parents and relatives through kindness to them, keeping ties and not severing them; those between him and his companions in upholding the rights of companionship in wealth and poverty, ease and hardship; and those between him and people, the contracts of dealings such as sale and hire and the like …"}},{"id":"infaq","ch":"mal","t":"أنفقوا من طيبات ما كسبتم","r":[2,267,268],"n":"أمر بالإنفاق من طيب الكسب وما أخرج الله من الأرض، والنهي عن قصد الخبيث بالإنفاق، وتحذير من وعد الشيطان بالفقر، ووعد الله بالمغفرة والفضل.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":267,"x":"يحث الباري عباده على الإنفاق مما كسبوا في التجارات، ومما أخرج لهم من الأرض من الحبوب والثمار، وهذا يشمل زكاة النقدين والعروض كلها المعدة للبيع والشراء والخارج من الأرض من الحبوب والثمار. ويدخل في عمومها الفرض والنفل، وأمر تعالى أن يقصدوا الطيب منها ولا يقصدوا الخبيث وهو الرديء الدون يجعلونه لله، ولو بذله لهم من لهم حق عليه لم يرتضوه، ولم يقبلوه إلا على وجه المغاضاة والإغماض، فالواجب إخراج الوسط من هذه الأشياء والكمال إخراج العالي، والممنوع إخراج الرديء فإن هذا لا يجزي عن الواجب، ولا يحصل فيه الثواب التام في المندوب.","en":"The Lord urges His servants to spend from what they earned through trade and from what He brought out of the earth for them of grains and fruits, which includes zakah on both currencies and all trade goods prepared for buying and selling and what comes out of the earth of grains and fruits. It includes the obligatory and the voluntary, and He commanded them to aim for the good of it and not aim for the bad, the worthless and poor which they offer to Allah though if the one who owed them a right gave them that, they would not accept it except by closing an eye. The duty is to give the average of these things, perfection is giving the best, and giving the worthless is forbidden since it does not suffice for the obligatory and does not bring the full reward in the recommended."}},{"id":"wasiyya","ch":"mal","t":"الوصية بالمعروف","r":[2,180,182],"n":"كتب الله على من حضره الموت وترك خيراً أن يوصي للوالدين والأقربين بالمعروف حقاً على المتقين، وتوعّد من يبدّل الوصية بعد ما سمعها.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":180,"x":"أي: فرض الله عليكم يا معشر المؤمنين {إذا حضر أحدكم الموت}؛ أي: أسبابه كالمرض المشرف على الهلاك وحضور أسباب المهالك وكان قد {ترك خيراً }؛ وهو المال الكثير عرفاً فعليه أن يوصي لوالديه وأقرب الناس إليه بالمعروف على قدر حاله من غير سرف ولا اقتصار على الأبعد دون الأقرب، بل يرتبهم على القرب والحاجة ولهذا أتى فيه بأفعل التفضيل، وقوله:{حقًّا على المتقين}؛ دل على وجوب ذلك، لأن الحق هو الثابت، وقد جعله الله من موجبات التقوى.","en":"That is: Allah has prescribed upon you, O believers, \"when death approaches one of you\", that is, its causes, such as a fatal illness or approaching causes of destruction, and he \"leaves wealth\", meaning much wealth by custom, that he should bequeath to his parents and nearest relatives in fairness according to his means, without extravagance and without limiting it to the more distant to the exclusion of the nearer, but ranking them by nearness and need, which is why the comparative form was used here. His words \"a duty upon the righteous\" show its obligation, since a duty is what is established, and He made it among the requirements of piety."}},{"id":"yatim","ch":"mal","t":"إيتاء اليتامى أموالهم","r":[4,2],"n":"وآتوا اليتامى أموالهم ولا تتبدلوا الخبيث بالطيب ولا تأكلوا أموالهم إلى أموالكم، فإنه كان حوباً كبيراً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":2,"x":"هذا أول ما أوصى به من حقوق الخلق في هذه السورة، وهم اليتامى الذين فقدوا آباءهم الكافلين لهم، وهم صغارٌ ضعافٌ، لا يقومون بمصالحهم، فأمر الرءوف الرحيم عباده أن يحسِنوا إليهم، وأن لا يَقْرَبوا أموالهم إلا بالتي هي أحسن، وأن يؤتوهم أموالهم ـ إذا بلغوا ورَشَدوا ـ كاملةً موفرةً، وأن لا يتبدلوا الخبيث الذي هو أكلُ مال اليتيم بغير حقٍّ {بالطيب} وهو الحلال الذي ما فيه حرجٌ ولا تَبِعة {ولا تأكلوا أموالهم إلى أموالكم}؛ أي: مع أموالكم، ففيه تنبيهٌ لقبح أكل مالِهم بهذه الحالة، التي هي قد استغنى بها الإنسان بما جعل الله له من الرزق في ماله؛ فمَنْ تجرَّأ على هذه الحالة؛ فقد أتى {حوباً كبيراً}؛ أي: إثماً عظيماً ووزراً جسيماً. ومن استبدال الخبيث بالطيِّب أن يأخذ الوليُّ من مال اليتيم النفيسِ ويجعلَ بدلَه من ماله الخسيسَ.","en":"This is the first thing He enjoined regarding the rights of creatures in this surah, namely the orphans who lost the fathers who sustained them while they are small and weak and cannot manage their own interests, so the Compassionate, Merciful commanded His servants to treat them well, not to approach their property except in the best way, to give them their property in full when they come of age and mature, and not to substitute the bad, which is consuming the orphan's property unjustly, for \"the good\", which is the lawful with no hardship or consequence, \"and do not consume their property with your own\", that is, together with your own, which warns of the ugliness of consuming their wealth in this state in which a person is already made independent by the provision Allah gave him; so whoever dares this has committed \"a great sin\", that is, a grave wrong and heavy burden. Part of substituting the bad for the good is that a guardian takes the orphan's precious property and puts his own worthless property in its place."}},{"id":"amana","ch":"mujtama","t":"أداء الأمانات والحكم بالعدل","r":[4,58],"n":"يأمر الله أن تؤدوا الأمانات إلى أهلها، وإذا حكمتم بين الناس أن تحكموا بالعدل، وأن ما يعظنا به نعمّا هو.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":58,"x":"الأمانات كلُّ ما اؤتُمِنَ عليه الإنسان وأُمِرَ بالقيام به، فأمر اللهُ عباده بأدائِها؛ أي: كاملة موفَّرة لا منقوصة ولا مبخوسةً ولا ممطولاً بها، ويدخُلُ في ذلك أماناتُ الولايات والأموال والأسرار والمأمورات التي لا يطَّلع عليها إلا الله.","en":"Trusts are everything a person is entrusted with and commanded to look after, so Allah commanded His servants to return them, that is, complete and full, not diminished, short-changed or delayed, and this includes the trusts of offices, wealth, secrets and the commands which only Allah knows."}},{"id":"qist","ch":"mujtama","t":"كونوا قوّامين بالقسط","r":[4,135],"n":"كونوا قوّامين بالقسط شهداء لله ولو على أنفسكم أو الوالدين والأقربين، ولا تتبعوا الهوى أن تعدلوا.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":135,"x":"يأمر تعالى عبادَه المؤمنين أن يكونوا {قوَّامين بالقسطِ شهداء لله}، والقوَّام صيغةُ مبالغةٍ؛ أي: كونوا في كلِّ أحوالكم قائمين بالقسطِ الذي هو العدل في حقوق الله وحقوق عباده؛ فالقِسْطُ في حقوق الله أن لا يُستعان بنعمه على معصيتِهِ، بل تُصرف في طاعته، والقِسْط في حقوق الآدميِّين أن تُؤدِّيَ جميع الحقوق التي عليك كما تَطْلُبُ حقوقك، فتؤدِّي النفقات الواجبة والدُّيون وتعامل الناس بما تحبُّ أن يعاملوك به من الأخلاق والمكافأة وغير ذلك.","en":"The Exalted commands His believing servants to be \"persistently standing firm in justice as witnesses for Allah\"; qawwam is an intensive form, meaning be in all your conditions upholding justice, which is fairness in Allah's rights and in His servants' rights. Justice in Allah's rights means not using His favours against disobeying Him, but spending them in obeying Him; justice in people's rights means you give all the rights you owe as you demand your own rights, so you give the obligatory maintenance and debts and treat people as you would like them to treat you of character, repayment and other things."}},{"id":"adl","ch":"mujtama","t":"العدل ولو مع من نبغض","r":[5,8],"n":"لا يحملنّكم بغض قوم على ألا تعدلوا، اعدلوا هو أقرب للتقوى.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":5,"ay":8,"x":"أي: {يا أيُّها الذين آمنوا}: بما أمروا بالإيمان به، قوموا بلازم إيمانكم، بأن تكونوا {قوَّامينَ لله شهداءَ بالقِسۡط}: بأن تنشط للقيام بالقِسْط حركاتكُم الظاهرة والباطنة، وأنْ يكونَ ذلك القيام لله وحدَه لا لغرض من الأغراض الدنيويَّة، وأن تكونوا قاصدين للقِسْط الذي هو العدل، لا الإفراط ولا التفريط في أقوالكم ولا أفعالكم، وقوموا بذلك على القريب والبعيد والصديق والعدو. {ولا يَجۡرِمَنَّكُم}؛ أي: يحملنَّكم بغض قوم {على أن لا تَعۡدِلوا}؛ كما يفعله مَن لا عدل عنده ولا قِسْط، بل كما تشهدون لوليِّكم؛ فاشهدوا عليه، وكما تشهدون على عدوِّكم؛ فاشهدوا له، ولو كان كافراً أو مبتدعاً؛ فإنَّه يجب العدل فيه وقبول ما يأتي به من الحقِّ؛ [لأنه حقٌّ]، لا لأنه قاله، ولا يُرَدُّ الحق لأجل قوله؛ فإن هذا ظلم للحقِّ.","en":"That is: \"O you who believe\": in what they were commanded to believe in, uphold what your faith requires, by being \"persistently standing firm for Allah, witnesses in justice\": that your outward and inward movements be energised to uphold justice, that this standing be for Allah alone and not for any worldly aim, and that you aim at justice, neither excess nor deficiency in your words or deeds, and stand for it against the near and the far, the friend and the enemy. \"And let not hatred of a people prevent you\": that is, lead you \"to be unjust\" as one who has no justice or fairness does, but as you testify for your ally, testify against him, and as you testify against your enemy, testify for him, even if he is a disbeliever or an innovator; for justice toward him is obligatory and so is accepting the truth he brings, because it is true, not because he said it, and truth is not rejected because of who says it, for that is injustice to the truth."}},{"id":"taawun","ch":"mujtama","t":"التعاون على البرّ والتقوى","r":[5,2],"n":"وتعاونوا على البر والتقوى ولا تعاونوا على الإثم والعدوان.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":5,"ay":2,"x":"{ولا تعاونَوا على الإثم}: وهو التَّجَرِّي على المعاصي التي يأثم صاحبُها ويُحَرَّجُ، {والعدوان}: وهو التعدِّي على الخلق في دمائهم وأموالهم وأعراضهم؛ فكلُّ معصية وظلم يجب على العبد كفُّ نفسِهِ عنه، ثم إعانة غيره على تركه.{واتقوا الله إن الله شديدُ العقاب}: على من عصاه وتجرَّأ على محارِمِه؛ فاحذروا المحارمَ؛ لئلا يحلَّ بكم عقابُه العاجل والآجل.","en":"\"And do not cooperate in sin\": which is daring toward disobedience for which the doer is sinful and blameworthy, \"and aggression\": which is transgression against people in their blood, wealth and honour; every disobedience and wrong that a servant must restrain himself from, then help others abandon. \"And fear Allah; indeed, Allah is severe in penalty\": toward whoever disobeys Him and dares His prohibitions; so beware the prohibitions lest His punishment, immediate and delayed, befall you."}},{"id":"daawa","ch":"mujtama","t":"أمة تدعو إلى الخير","r":[3,104],"n":"ولتكن منكم أمة يدعون إلى الخير ويأمرون بالمعروف وينهون عن المنكر، وأولئك هم المفلحون.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":3,"ay":104,"x":"وأمرهم بتتميم هذه الحالة، والسبب الأقوى الذي يتمكنون به من إقامة دينهم بأن يتصدى منهم طائفة يحصل فيها الكفاية {يدعون إلى الخير}؛ وهو الدين: أصوله وفروعه وشرائعه {ويأمرون بالمعروف}؛ وهو ما عرف حسنه شرعاً وعقلاً {وينهون عن المنكر}؛ وهو ما عرف قبحه شرعاً وعقلاً {وأولئك هم المفلحون}؛ المدركون لكل مطلوب الناجون من كل مرهوب، ويدخل في هذه الطائفة أهل العلم والتعليم والمتصدون للخطابة ووعظ الناس عموماً وخصوصاً والمحتسبون، الذين يقومون بإلزام الناس بإقامة الصلوات وإيتاء الزكاة والقيام بشرائع الدين، وينهونهم عن المنكرات. فكل من دعا الناس إلى خير على وجه العموم أو على وجه الخصوص، أو قام بنصيحة عامة أو خاصة فإنه داخل في هذه الآية الكريمة.","en":"He commanded them to complete this state, and the strongest means by which they can establish their religion is that a group among them, in whom there is sufficiency, take it upon themselves \"to invite to good\", which is the religion, its fundamentals, branches and laws, \"and enjoin what is right\", which is what is known to be good by law and reason, \"and forbid what is wrong\", which is what is known to be bad by law and reason; \"and those are the successful\", the ones who attain every aim and are saved from every fear. This group includes scholars and teachers, those engaged in preaching and admonishing people generally and specifically and those who hold people to account, who see to people establishing prayers, giving zakah and upholding the laws of the religion and forbid them wrongdoing. So everyone who calls people to good, generally or specifically, or gives general or particular advice, falls within this noble verse."}},{"id":"hikma","ch":"mujtama","t":"ادع إلى سبيل ربك بالحكمة","r":[16,125],"n":"ادع إلى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي أحسن.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":16,"ay":125,"x":"أي: ليكن دعاؤك للخلق مسلمهم وكافرهم إلى سبيل ربِّك المستقيم المشتمل على العلم النافع والعمل الصالح، {بالحكمة}؛ أي: كل أحدٍ على حسب حاله وفَهْمه وقَبوله وانقياده، ومن الحكمة الدعوةُ بالعلم لا بالجهل، والبدأة بالأهمِّ فالأهمِّ، وبالأقربِ إلى الأذهان والفهم، وبما يكون قَبوله أتمَّ، وبالرفق واللين …","en":"That is: let your calling of creation, Muslim and disbeliever, to the straight path of your Lord, which comprises beneficial knowledge and righteous action, be \"with wisdom\", that is, each person according to his state, understanding, acceptance and compliance; part of wisdom is calling with knowledge, not ignorance, starting with the most important then the next, with what is nearest to minds and understanding and with what will be most fully accepted, and with gentleness and softness …"}},{"id":"islah","ch":"mujtama","t":"الإصلاح بين المؤمنين","r":[49,9,10],"n":"إن اقتتلت طائفتان من المؤمنين فأصلحوا بينهما، فإن بغت إحداهما فقاتلوا التي تبغي حتى تفيء إلى أمر الله، وأقسطوا؛ إنما المؤمنون إخوة فأصلحوا بين أخويكم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":49,"ay":9,"x":"وقولُه:{فإن فاءتۡ فأصۡلِحوا بينَهما بالعَدۡلِ}: هذا أمرٌ بالصُّلح وبالعدل في الصلح؛ فإنَّ الصُّلح قد يوجد، ولكن لا يكون بالعدل، بل بالظُّلم والحيف على أحد الخصمين؛ فهذا ليس هو الصُّلح المأمورُ به، فيجب أن لا يراعَى أحدهما لقرابةٍ أو وطنٍ أو غير ذلك من المقاصد والأغراض، التي توجب العدول عن العدل. {إنَّ اللهَ يحبُّ المُقۡسِطينَ}؛ أي: العادلين في حكمهم بين الناس، وفي جميع الولايات التي تولوها، حتى إنه قد يدخل في ذلك عدلُ الرجل في أهله وعيالِه في أداء حقوقهم، وفي الحديث الصحيح:«المقسِطون عند الله على منابرَ من نورٍ؛ الذين يعدِلون في حكمِهم وأهليهم وما ولوا».","en":"His words \"then if it returns, make settlement between them with justice\": this is a command to reconcile and to be just in the reconciliation, for reconciliation may exist but not with justice, rather with injustice and partiality to one of the two parties, and that is not the reconciliation commanded; so one must not favour either because of kinship, homeland or other aims that cause deviation from justice. \"Indeed, Allah loves those who act justly\": that is, those just in their judgment between people and in all the offices they hold, so that it even includes a man's justice with his family and dependants in fulfilling their rights; in the authentic hadith: \"The just will be with Allah on pulpits of light: those who are just in their judgment, their families and what they are put in charge of\"."}},{"id":"taa","ch":"mujtama","t":"طاعة الله والرسول وأولي الأمر بالمعروف","r":[4,59],"n":"أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم، وإن تنازعتم في شيء فردوه إلى الله والرسول إن كنتم تؤمنون بالله واليوم الآخر.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":4,"ay":59,"x":"ثم أمر بطاعتِهِ وطاعة رسولِهِ، وذلك بامتثال أمرهما الواجب والمستحبِّ واجتناب نهيهِما، وأمر بطاعة أولي الأمر، وهم الولاة على الناس من الأمراء والحكَّام والمفتين؛ فإنَّه لا يستقيمُ للناس أمرُ دينهم ودُنياهم إلاَّ بطاعِتِهم والانقيادِ لهم. طاعةً لله ورغبةً فيما عنده، ولكن بشرط أن لا يأمروا بمعصية الله؛ فإنْ أمروا بذلك؛ فلا طاعة لمخلوق في معصية الخالق.","en":"Then He commanded obedience to Him and His Messenger, by complying with their commands, obligatory and recommended, and avoiding their prohibitions, and commanded obedience to those in authority, who are the rulers over people, the leaders, judges and muftis, for the matter of people's religion and worldly life cannot be set right except by obeying them and submitting to them, in obedience to Allah and desire for what is with Him, but on condition that they do not command disobedience to Allah; if they command it, there is no obedience to a creature in disobedience to the Creator."}},{"id":"asr","ch":"tawasi","t":"التواصي بالحق والصبر","r":[103,1,3],"n":"الإنسان في خسر إلا الذين آمنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":103,"ay":1,"x":"والتَّواصي بالحقِّ الذي هو الإيمان والعمل الصالح؛ أي: يوصي بعضُهم بعضاً بذلك، ويحثُّه عليه، ويرغِّبه فيه. والتَّواصي بالصَّبر على طاعة الله، وعن معصية الله، وعلى أقدار الله المؤلمة.","en":"Counselling one another to truth, which is faith and righteous action, that is, they urge one another to it, encourage it and make it desirable. And counselling one another to patience in obeying Allah, in refraining from disobeying Allah and over Allah's painful decrees."}},{"id":"balad","ch":"tawasi","t":"التواصي بالصبر وبالمرحمة","r":[90,12,18],"n":"فسّر الله العقبة: فكّ رقبة أو إطعام في يوم ذي مسغبة يتيماً أو مسكيناً، ثم كان من الذين آمنوا وتواصوا بالصبر وتواصوا بالمرحمة.","wd":1,"q":{"w":"السعدي","bk":"saadi","s":90,"ay":12,"x":"ثم فسَّر هذه العقبة بقوله: {فكُّ رقبةٍ}؛ أي: فكُّها من الرقِّ بعتقها أو مساعدتها على أداء كتابتها، ومن باب أولى فكاك الأسير المسلم عند الكفار، {أو إطعامٌ في يوم ذي مَسۡغَبَةٍ}؛ أي: مجاعةٍ شديدةٍ؛ بأن يطعم وقت الحاجة أشدَّ الناس حاجةً، {يتيماً ذا مَقۡرَبَةٍ}؛ أي: جامعاً بين كونه يتيماً وفقيراً ذا قرابة، {أو مسكيناً ذا مَتۡرَبَةٍ}؛ أي: قد لزق بالتراب من الحاجة والضَّرورة.","en":"Then He explained this steep path with His words \"freeing a slave\": freeing him from slavery by emancipating him or helping him pay his contract of manumission, and all the more so ransoming a Muslim captive from the disbelievers, \"or feeding on a day of severe hunger\", that is, great famine, by feeding at the time of need the most needy of people, \"an orphan of near relationship\", that is, combining being an orphan and poor and a relative, \"or a needy person in dust\", that is, one clinging to the dust from need and necessity."}}],"ay":{"27":"يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","28":"ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا وَٱلسَّمَآءَ بِنَآءٗ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا وَأَنتُمۡ تَعۡلَمُونَ","89":"وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ","138":"وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ","139":"أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ","158":"فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ","183":"۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","186":"كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ","187":"فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","188":"فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","244":"حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ","245":"فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ","273":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ","274":"ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","284":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ","285":"فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ","286":"وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","288":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","394":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ","395":"وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ","396":"وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","492":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ","494":"وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا","503":"يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","511":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا","521":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا","522":"وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا","528":"۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا","550":"۞ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا","551":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا","623":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا","627":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","669":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ","670":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","676":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ","939":"۞ قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ","940":"وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ","941":"وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ","1152":"خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ","1990":"۞ إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ","2025":"ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","2051":"۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا","2052":"وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا","2053":"رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّٰبِينَ غَفُورٗا","2054":"وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا","2055":"إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا","2056":"وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا","2057":"وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا","2058":"إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا","2059":"وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـٔٗا كَبِيرٗا","2060":"وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا","2061":"وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا","2062":"وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا","2063":"وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا","2064":"وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا","2065":"وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا","2066":"كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهٗا","2067":"ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومٗا مَّدۡحُورًا","2479":"وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ","2817":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ","2818":"فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدٗا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ","2820":"قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ","2821":"وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ","3347":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حُسۡنٗاۖ وَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","3480":"وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ","3481":"وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ","3482":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ","3483":"وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفٗاۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","3484":"يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٖ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ","3485":"يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ","3486":"وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٖ","3487":"وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ","3573":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا","3574":"وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا","3602":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا","3603":"يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا","4250":"وَمَنۡ أَحۡسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ","4251":"وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ وَلِيٌّ حَمِيمٞ","4252":"وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٖ","4284":"۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ","4524":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ","4617":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ","4620":"وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ","4621":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ","4622":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ","4623":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ","5234":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ","6034":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","6035":"فَكُّ رَقَبَةٍ","6036":"أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","6037":"يَتِيمٗا ذَا مَقۡرَبَةٍ","6038":"أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","6039":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","6040":"أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ","6176":"وَٱلۡعَصۡرِ","6177":"إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ","6178":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ"},"nay":97,"nwd":13};
